-- =====================================================================
-- Migration 000007: fitur Jasa (KEPUTUSAN #20 frontend, 2 Nov 2026).
-- Tabel services + service_categories, menu Konten > Jasa, izin
-- content.service.read / content.service.manage untuk SUPER_ADMIN dan
-- ADMIN_KONTEN, serta 7 jasa contoh (bisa diubah/nonaktifkan di admin).
-- Dipakai golang-migrate (make migrate-up) atau dijalankan manual di
-- DBeaver -> Execute SQL Script (Alt+X). Aman dijalankan ulang.
-- =====================================================================
BEGIN;

CREATE TABLE IF NOT EXISTS crm_schema.services (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(150) NOT NULL UNIQUE,
    summary VARCHAR(160) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    image_url VARCHAR(2048) NULL,
    service_area VARCHAR(100) NULL,
    sort_order INT NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_services_active_order ON crm_schema.services (is_active, sort_order, id);

-- Kategori produk terkait: jasa tampil di halaman produk dari kategori ini (dan anak-anaknya).
CREATE TABLE IF NOT EXISTS crm_schema.service_categories (
    service_id BIGINT NOT NULL REFERENCES crm_schema.services(id) ON DELETE CASCADE,
    category_id BIGINT NOT NULL REFERENCES crm_schema.categories(id) ON DELETE CASCADE,
    PRIMARY KEY (service_id, category_id)
);
CREATE INDEX IF NOT EXISTS idx_service_categories_category ON crm_schema.service_categories (category_id);

DROP TRIGGER IF EXISTS trg_services_updated_at ON crm_schema.services;
CREATE TRIGGER trg_services_updated_at BEFORE UPDATE ON crm_schema.services
    FOR EACH ROW EXECUTE FUNCTION crm_schema.set_updated_at();

-- Skrip manual sebelumnya (3 Nov 2026) membuat menu 'content.services' di bawah grup 'content' dengan izin
-- service.view/create/update. Disatukan ke kode baku content.service.* agar cocok dengan backend.
UPDATE crm_schema.menus SET code='content.service', parent_id=NULL, sort_order=76
 WHERE code='content.services' AND NOT EXISTS (SELECT 1 FROM crm_schema.menus WHERE code='content.service');

INSERT INTO crm_schema.menus (name,code,route,icon,sort_order,is_active) VALUES ('Jasa','content.service','/admin/jasa','wrench',76,TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO crm_schema.permissions (menu_id,code,action,description) SELECT id,'content.service.read','read','RBAC content.service.read' FROM crm_schema.menus WHERE code='content.service' ON CONFLICT (code) DO NOTHING;
INSERT INTO crm_schema.role_permissions (role_id,permission_id) SELECT r.id,p.id FROM crm_schema.roles r CROSS JOIN crm_schema.permissions p WHERE r.code='SUPER_ADMIN' AND p.code='content.service.read' ON CONFLICT (role_id,permission_id) DO NOTHING;
INSERT INTO crm_schema.role_permissions (role_id,permission_id) SELECT r.id,p.id FROM crm_schema.roles r CROSS JOIN crm_schema.permissions p WHERE r.code='ADMIN_KONTEN' AND p.code='content.service.read' ON CONFLICT (role_id,permission_id) DO NOTHING;
INSERT INTO crm_schema.permissions (menu_id,code,action,description) SELECT id,'content.service.manage','manage','RBAC content.service.manage' FROM crm_schema.menus WHERE code='content.service' ON CONFLICT (code) DO NOTHING;
INSERT INTO crm_schema.role_permissions (role_id,permission_id) SELECT r.id,p.id FROM crm_schema.roles r CROSS JOIN crm_schema.permissions p WHERE r.code='SUPER_ADMIN' AND p.code='content.service.manage' ON CONFLICT (role_id,permission_id) DO NOTHING;
INSERT INTO crm_schema.role_permissions (role_id,permission_id) SELECT r.id,p.id FROM crm_schema.roles r CROSS JOIN crm_schema.permissions p WHERE r.code='ADMIN_KONTEN' AND p.code='content.service.manage' ON CONFLICT (role_id,permission_id) DO NOTHING;

-- Role lain yang sempat diberi izin lama tetap mendapat padanannya, lalu izin lama dihapus.
INSERT INTO crm_schema.role_permissions (role_id,permission_id)
 SELECT DISTINCT rp.role_id, n.id FROM crm_schema.role_permissions rp
 JOIN crm_schema.permissions o ON o.id=rp.permission_id
 JOIN crm_schema.permissions n ON n.code = CASE o.code WHEN 'service.view' THEN 'content.service.read' ELSE 'content.service.manage' END
 WHERE o.code IN ('service.view','service.create','service.update')
 ON CONFLICT (role_id,permission_id) DO NOTHING;
DELETE FROM crm_schema.permissions WHERE code IN ('service.view','service.create','service.update');
-- Grup 'content' tanpa route dari skrip manual dihapus bila sudah kosong (menu konten lain tidak memakai induk).
DELETE FROM crm_schema.menus m WHERE m.code='content' AND m.route IS NULL
 AND NOT EXISTS (SELECT 1 FROM crm_schema.menus c WHERE c.parent_id=m.id)
 AND NOT EXISTS (SELECT 1 FROM crm_schema.permissions p WHERE p.menu_id=m.id);

-- Jasa contoh dari data mock frontend. Gambar dan kategori terkait diisi admin lewat Konten > Jasa.
INSERT INTO crm_schema.services (name,slug,summary,description,service_area,sort_order) VALUES
  ('Jasa pasang keramik & granit', 'pasang-keramik-granit', 'Pemasangan keramik dan granit untuk lantai maupun dinding, termasuk perataan dan pengisian nat.', E'Lantai dan dinding yang rata dan rapi bergantung pada cara pemasangannya. Tim kami membantu memasang keramik atau granit yang kamu beli di Transhome.\n\n## Yang dikerjakan\n\n- Mengecek kerataan lantai atau dinding sebelum dipasang.\n- Memasang keramik atau granit dengan perekat yang sesuai.\n- Mengisi nat dan membersihkan sisa pemasangan.\n\n## Siapkan sebelum konsultasi\n\n- Ukuran ruangan (panjang × lebar) atau luas dinding.\n- Foto kondisi lantai atau dinding sekarang.\n- Jenis dan ukuran keramik yang dipilih.', 'Sleman dan sekitarnya', 1),
  ('Jasa pengecatan', 'pengecatan', 'Pengecatan dinding dalam dan luar rumah, dari persiapan permukaan sampai lapisan akhir.', E'Cat yang awet dimulai dari permukaan yang disiapkan dengan benar. Tim kami membantu mengecat dinding dalam maupun luar rumah.\n\n## Yang dikerjakan\n\n- Membersihkan dan menambal bagian dinding yang retak ringan.\n- Mengoleskan cat dasar, lalu cat warna.\n- Melindungi lantai dan perabot dari cipratan cat.\n\n## Siapkan sebelum konsultasi\n\n- Luas atau ukuran dinding yang akan dicat.\n- Foto dinding sekarang, terutama bagian yang mengelupas atau lembap.\n- Warna dan jenis cat yang diinginkan, bila sudah ada.', 'Sleman dan sekitarnya', 2),
  ('Jasa pasang perlengkapan kamar mandi', 'pasang-perlengkapan-kamar-mandi', 'Pemasangan kloset, wastafel, kran, shower, dan pemanas air.', E'Kloset, wastafel, dan kran yang terpasang rapat tidak mudah bocor. Tim kami membantu memasang perlengkapan kamar mandi yang kamu beli di Transhome.\n\n## Yang dikerjakan\n\n- Memasang kloset, wastafel, kran, shower, atau pemanas air.\n- Menyambungkan ke saluran air bersih dan pembuangan.\n- Mengecek tidak ada rembesan setelah terpasang.\n\n## Siapkan sebelum konsultasi\n\n- Foto kamar mandi dan posisi saluran air.\n- Ukuran ruangan.\n- Daftar barang yang akan dipasang.', 'Sleman dan sekitarnya', 3),
  ('Jasa pasang AC & elektronik', 'pasang-ac-elektronik', 'Pemasangan AC, lampu, stop kontak, dan perangkat elektronik rumah.', E'Perangkat elektronik bekerja paling baik bila dipasang dengan benar. Tim kami membantu memasang AC, lampu, dan perangkat elektronik rumah.\n\n## Yang dikerjakan\n\n- Memasang unit AC dalam dan luar ruangan.\n- Memasang lampu, sakelar, dan stop kontak.\n- Menguji perangkat setelah terpasang.\n\n## Siapkan sebelum konsultasi\n\n- Foto ruangan dan dinding tempat perangkat akan dipasang.\n- Ukuran ruangan untuk AC.\n- Daya listrik rumah (VA), bila tahu.', 'Sleman dan sekitarnya', 4),
  ('Jasa service & perbaikan', 'service-perbaikan', 'Servis dan perbaikan AC, pemanas air, pompa air, dan perangkat elektronik rumah yang bermasalah.', E'AC yang kurang dingin, pemanas air yang tidak panas, atau pompa air yang lemah bisa diperiksa dan diperbaiki tanpa harus langsung membeli baru. Tim kami membantu servis rutin maupun perbaikan.\n\n## Yang dikerjakan\n\n- Servis rutin AC: membersihkan unit dan mengecek kinerjanya.\n- Memeriksa dan memperbaiki pemanas air, pompa air, dan perangkat elektronik rumah.\n- Memberi saran bila ada komponen yang perlu diganti.\n\n## Siapkan sebelum konsultasi\n\n- Merek dan jenis perangkat yang bermasalah.\n- Keluhan singkat, misalnya "AC menetes" atau "air tidak panas".\n- Foto atau video perangkat saat menyala, bila ada.', 'Sleman dan sekitarnya', 5),
  ('Jasa pasang pintu & jendela', 'pasang-pintu-jendela', 'Pemasangan pintu, jendela, kusen, kunci, dan engsel untuk rumah baru maupun renovasi.', E'Pintu dan jendela yang terpasang lurus mudah dibuka, rapat, dan aman dikunci. Tim kami membantu memasang pintu, jendela, beserta kunci dan engselnya.\n\n## Yang dikerjakan\n\n- Memasang kusen, daun pintu, dan jendela.\n- Memasang engsel, kunci, dan pegangan pintu.\n- Menyetel pintu dan jendela supaya rapat dan tidak seret.\n\n## Siapkan sebelum konsultasi\n\n- Ukuran lubang pintu atau jendela (lebar × tinggi).\n- Foto lokasi pemasangan.\n- Jenis pintu atau jendela yang dipilih, bila sudah ada.', 'Sleman dan sekitarnya', 6),
  ('Jasa antar & rakit perabot', 'antar-rakit-perabot', 'Pengantaran dan perakitan sofa, lemari, meja, kasur, dan perabot rumah lainnya sampai siap dipakai.', E'Perabot besar seperti sofa, lemari, dan kasur repot dibawa dan dirakit sendiri. Tim kami mengantar perabot ke rumahmu dan merakitnya sampai siap dipakai.\n\n## Yang dikerjakan\n\n- Mengantar perabot dari toko ke rumahmu.\n- Merakit lemari, meja, rak, dan tempat tidur.\n- Menata perabot di ruangan yang kamu tentukan.\n\n## Siapkan sebelum konsultasi\n\n- Daftar perabot yang akan diantar atau dirakit.\n- Alamat lengkap dan patokannya.\n- Lebar pintu, lorong, atau tangga yang akan dilewati perabot besar.', 'Sleman dan sekitarnya', 7)
ON CONFLICT (slug) DO NOTHING;

COMMIT;
